var index = 0;
function checkInputEdit(num){
	index = num;
	var accountID="";
	if($("#r" + num + "_accountid_last").val() == ''){
		accountID = $("#r" + num + "_accountid_1").val();
	}else{
		accountID = $("#r" + num + "_accountid_last").val();
	}
	if(accountID == ""){
		$("#origine_amount").val("");
		$("#origine_unitprice").val("");
	}
	$.post("do?action=zhsx_common_jzpz&start=checkInputEdit&entityID=" + $('#entityID').val() + "&accountID="+ accountID , null,
