function draw_line(arg_color,debit_obj_name,lend_obj_name )
{ //参数： div_id_str，形状_str, 内容文本_str，宽度_int，高度_int，字体_str，色彩_str

    var jg = new jsGraphics("div_for_drawLine_only");
    jg.setColor(arg_color); //"RED");// else jg.setColor("BLACK");

    obj_debit = GetAbsoluteLocation( document.getElementById(debit_obj_name));
    obj_lend = GetAbsoluteLocation( document.getElementById(lend_obj_name));

    x1=obj_debit.absoluteLeft;
    y1=obj_debit.absoluteTop + obj_debit.offsetHeight;
    x2=obj_lend.absoluteLeft + obj_lend.offsetWidth;
    y2=obj_lend.absoluteTop;
    jg.drawLine(x1,y1,x2,y2);
    jg.paint();
}
function AbsolutePos()
{ //保存绝对位置的 对象 
     this.absoluteTop = 0;
     this.absoluteLeft = 0;
     this.offsetWidth = 0;
     this.offsetHeight = 0;
}
function GetAbsoluteLocation(element) 
{   //计算绝对位置，返回对象 AbsolutePos ,  20080312 test ok 
    var obj = new AbsolutePos();
    if ( arguments.length != 1 || element == null ) 
    { 
        return obj; 
    } 
    var elmt = element; 
    obj.absoluteTop    = elmt.offsetTop; 
    obj.absoluteLeft   = elmt.offsetLeft; 
    obj.offsetWidth    = elmt.offsetWidth; 
    obj.offsetHeight   = elmt.offsetHeight; 
    while( elmt = elmt.offsetParent ) 
    { 
          // add this judge 
        if ( elmt.style.position == 'absolute' || elmt.style.position == 'relative'  
            || ( elmt.style.overflow != 'visible' && elmt.style.overflow != '' ) ) 
        { 
            break; 
        }  
        obj.absoluteTop  += elmt.offsetTop; 
        obj.absoluteLeft += elmt.offsetLeft; 
    } 
    return obj;
}
